-- Arbeitsrecht Berufsbildung > Kündigungsschutz > Schriftform (§ 2 NachwG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb einem Fachinformatiker die wesentlichen Vertragsbedingungen schriftlich nachweisen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 2 NachwG verlangt schriftlichen Nachweis"}, {"text": "Nein", "correct": false, "because": "Schriftform ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb die Vertragsbedingungen eines Fachinformatikers mündlich vereinbaren, ohne sie schriftlich festzuhalten?', 2, '[{"text": "Nein", "correct": true, "because": "§ 2 NachwG fordert Schriftform für den Nachweis"}, {"text": "Ja", "correct": false, "because": "Mündlich nicht ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Schriftform gemäß § 2 NachwG auch die Vergütung eines Fachinformatikers umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt Angabe der Vergütung"}, {"text": "Nein", "correct": false, "because": "Vergütung ist wesentliche Bedingung"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Ausbildungsbetrieb die Vertragsbedingungen eines Fachinformatikers per E-Mail nachweisen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 2 NachwG verlangt eigenhändige Unterschrift, keine elektronische Form"}, {"text": "Ja", "correct": false, "because": "E-Mail genügt nicht der Schriftform"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker auf die schriftliche Festlegung der Vertragsbedingungen verzichten?', 2, '[{"text": "Nein", "correct": true, "because": "§ 2 NachwG ist zwingendes Recht"}, {"text": "Ja", "correct": false, "because": "Verzicht ist nicht möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage fordert die Schriftform für die Vertragsbedingungen eines Fachinformatikers?', 2, '[{"text": "§ 2 NachwG", "correct": true, "because": "Regelt den schriftlichen Nachweis"}, {"text": "§ 22 BBiG", "correct": false, "because": "Bezieht sich auf Kündigungen"}, {"text": "§ 14 BBiG", "correct": false, "because": "Regelt Arbeitgeberpflichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedingung muss gemäß § 2 NachwG schriftlich nachgewiesen werden?', 3, '[{"text": "Die Dauer der Ausbildung", "correct": true, "because": "§ 2 Abs. 1 Nr. 2 NachwG fordert dies"}, {"text": "Persönliche Hobbys", "correct": false, "because": "Nicht relevant"}, {"text": "Nur der Arbeitsbeginn", "correct": false, "because": "Zu unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie lange hat ein Betrieb Zeit, einem Fachinformatiker die Vertragsbedingungen schriftlich nachzuweisen?', 2, '[{"text": "Spätestens 1 Monat nach Arbeitsbeginn", "correct": true, "because": "§ 2 Abs. 1 NachwG legt dies fest"}, {"text": "Innerhalb von 6 Monaten", "correct": false, "because": "Zu spät"}, {"text": "Jederzeit während der Ausbildung", "correct": false, "because": "Frist ist vorgegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, die Schriftform gemäß § 2 NachwG für einen Fachinformatiker einzuhalten?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 2 NachwG verpflichtet den Arbeitgeber"}, {"text": "Die IHK", "correct": false, "because": "IHK hat keine Rolle dabei"}, {"text": "Der Auszubildende", "correct": false, "because": "Nicht seine Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb die Schriftform gemäß § 2 NachwG für einen Fachinformatiker nicht einhält?', 3, '[{"text": "Der Auszubildende kann Nachbesserung verlangen", "correct": true, "because": "§ 2 NachwG ist einklagbar"}, {"text": "Der Vertrag wird automatisch ungültig", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Keine Konsequenzen", "correct": false, "because": "Verstoß hat Folgen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vertragsbedingungen müssen gemäß § 2 NachwG für einen Fachinformatiker schriftlich nachgewiesen werden?', 4, '[{"text": "Beginn der Ausbildung", "correct": true, "because": "§ 2 Abs. 1 Nr. 2 NachwG fordert dies"}, {"text": "Vergütung", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt dies"}, {"text": "Lieblingsprogrammiersprache", "correct": false, "because": "Nicht relevant"}, {"text": "Dauer der Ausbildung", "correct": true, "because": "§ 2 Abs. 1 Nr. 2 NachwG schreibt dies vor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt § 2 NachwG an die Schriftform für einen Fachinformatiker?', 3, '[{"text": "Eigenhändige Unterschrift", "correct": true, "because": "§ 2 NachwG verlangt dies"}, {"text": "Nachweis spätestens 1 Monat nach Beginn", "correct": true, "because": "§ 2 Abs. 1 NachwG legt dies fest"}, {"text": "Elektronische Form genügt", "correct": false, "because": "Nicht ausreichend"}, {"text": "Angabe wesentlicher Bedingungen", "correct": true, "because": "§ 2 Abs. 1 NachwG fordert dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb tun, um § 2 NachwG für einen Fachinformatiker einzuhalten?', 4, '[{"text": "Schriftlichen Nachweis der Vertragsbedingungen erstellen", "correct": true, "because": "§ 2 NachwG schreibt dies vor"}, {"text": "Eigenhändig unterschreiben", "correct": true, "because": "Erforderlich für Schriftform"}, {"text": "Nur mündlich informieren", "correct": false, "because": "Nicht ausreichend"}, {"text": "Innerhalb eines Monats übergeben", "correct": true, "because": "§ 2 Abs. 1 NachwG legt dies fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der die Schriftform gemäß § 2 NachwG nicht einhält?', 3, '[{"text": "Nachbesserungsforderung durch den Auszubildenden", "correct": true, "because": "Rechtlich durchsetzbar"}, {"text": "Bußgelder durch Behörden", "correct": true, "because": "Verstoß kann sanktioniert werden"}, {"text": "Automatische Vertragsauflösung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK kann einschreiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen müssen nicht schriftlich gemäß § 2 NachwG für einen Fachinformatiker nachgewiesen werden?', 3, '[{"text": "Vergütung", "correct": false, "because": "§ 2 Abs. 1 Nr. 6 NachwG fordert dies"}, {"text": "Persönliche Präferenzen des Auszubildenden", "correct": true, "because": "Nicht wesentlich"}, {"text": "Arbeitszeit", "correct": false, "because": "§ 2 Abs. 1 Nr. 5 NachwG verlangt dies"}, {"text": "Beginn der Ausbildung", "correct": false, "because": "§ 2 Abs. 1 Nr. 2 NachwG schreibt dies vor"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Betrieb muss die Vertragsbedingungen eines Fachinformatikers schriftlich nachweisen. b) Die Schriftform kann per E-Mail erfüllt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schriftform Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) § 2 NachwG verlangt die Angabe der Vergütung. b) Der Nachweis muss innerhalb eines Monats erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 und Frist bestätigen dies"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Schriftform gemäß § 2 NachwG erfordert eine eigenhändige Unterschrift. b) Ein Fachinformatiker kann auf den Nachweis verzichten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unterschrift erforderlich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Betrieb muss die Dauer der Ausbildung schriftlich nachweisen. b) Die Schriftform ist nur für Kündigungen vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dauer ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) § 2 NachwG gilt für den Ausbildungsvertrag eines Fachinformatikers. b) Ein Verstoß gegen die Schriftform führt zur Vertragsauflösung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NachwG gilt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');
